#!/bin/bash\n\n# Harmony Lifebond Tasks - Android Build Script\n# This script builds the APK for Android installation\n\nset -e\n\necho \"🚀 Starting Harmony Lifebond Tasks Android Build...\"\n\ncd packages/mobile\n\necho \"📦 Installing dependencies...\"\nnpm install\n\necho \"🔨 Building Android APK...\"\necho \"This will take a few minutes...\"\n\nnpm run build:android\n\necho \"✅ Build complete!\"\necho \"\"\necho \"📱 Your APK is ready to install on Android!\"\necho \"\"\necho \"Installation options:\"\necho \"1. Direct Install (if phone connected via USB):\"\necho \"   npx eas build --platform android --local\"\necho \"\"\necho \"2. Download from Expo:\"\necho \"   - Run: npx eas build --platform android\"\necho \"   - Visit: https://expo.dev/builds\"\necho \"   - Download APK and transfer to phone\"\necho \"\"\necho \"3. Manual Installation:\"\necho \"   - Find APK file in build output\"\necho \"   - Transfer to phone via USB\"\necho \"   - Open file manager on phone\"\necho \"   - Tap APK to install\"\n